svg.script:
    (() => {
      "use strict";

      const DB_NAME = "local-play-vault";
      const DB_VERSION = 1;
      const CHUNK_BYTES = 8 * 1024 * 1024;
      const TRACK_WIDTH = 382;

      // Optional: paste a Google Drive API key here to skip the one-time
      // setup prompt. A key can also be supplied as ?key=... or #key=... in
      // the URL. Keys are stored only in this browser's localStorage.
      const GOOGLE_DRIVE_API_KEY = "AIzaSyBDfJdhDDfTG4ptZhhPYI5js3me3E9M0dk";
      const DRIVE_KEY_STORAGE = "local-play:drive-api-key";
      let rejectedDriveKey = "";

      const GAMES = {
        fortnite: {
          name: "Fortnite",
          file: "fortnite.html",
          id: "1my4YsCJxV6pIWScbL45aakz6rXzqcz7m",
          bytes: 1820722778,
          accent: "#ff8b64",
          accent2: "#b99cff"
        },
        minecraft: {
          name: "Minecraft",
          file: "direct-connect-2026-10-19.html",
          id: "1ecAl_ixAGh9IS_hRS5w5QUltPdPSPCll",
          bytes: 76006109,
          accent: "#68e7a2",
          accent2: "#34d399"
        }
      };

      const app = {
        meta: { fortnite: null, minecraft: null },
        activeDownload: null,
        launching: { fortnite: false, minecraft: false },
        clearing: { fortnite: false, minecraft: false }
      };

      const ui = {};
      let dbPromise = null;
      let persistenceRequested = false;

      class DownloadError extends Error {
        constructor(code, message) {
          super(message || code);
          this.name = "DownloadError";
          this.code = code;
        }
      }

      function saveDriveKey(key) {
        rejectedDriveKey = "";
        try { localStorage.setItem(DRIVE_KEY_STORAGE, key); } catch (_) {}
      }

      function forgetDriveKey() {
        try { localStorage.removeItem(DRIVE_KEY_STORAGE); } catch (_) {}
      }

      function readDriveKey() {
        try {
          const params = new URLSearchParams(location.search);
          const hash = location.hash && location.hash.charAt(0) === "#"
            ? location.hash.slice(1)
            : location.hash;
          const hashParams = new URLSearchParams(hash || "");
          const fromUrl = params.get("key") || params.get("driveKey") ||
            hashParams.get("key") || hashParams.get("driveKey");
          if (fromUrl) {
            const trimmed = fromUrl.trim();
            if (trimmed && trimmed !== rejectedDriveKey) {
              saveDriveKey(trimmed);
              return trimmed;
            }
          }
        } catch (_) {}

        const configured = GOOGLE_DRIVE_API_KEY.trim();
        if (configured && configured !== rejectedDriveKey) return configured;
        try {
          const saved = (localStorage.getItem(DRIVE_KEY_STORAGE) || "").trim();
          return saved && saved !== rejectedDriveKey ? saved : "";
        } catch (_) { return ""; }
      }

      function ensureDriveKey() {
        const existing = readDriveKey();
        if (existing) return existing;

        const entered = window.prompt(
          "One-time setup: Google Drive needs an API key for browser downloads.\n\n" +
          "Create a key in Google Cloud with the Drive API enabled, then paste it here. " +
          "It is stored only in this browser. You can revoke it at any time.",
          ""
        );
        const key = (entered || "").trim();
        if (key) saveDriveKey(key);
        return key;
      }

      function downloadUrl(game, key) {
        return "https://www.googleapis.com/drive/v3/files/" +
          encodeURIComponent(game.id) + "?alt=media&key=" + encodeURIComponent(key);
      }

      function formatBytes(bytes) {
        const value = Number(bytes) || 0;
        if (value < 1000) return Math.round(value) + " B";
        const units = ["KB", "MB", "GB", "TB"];
        let n = value;
        let unit = -1;
        do {
          n /= 1000;
          unit += 1;
        } while (n >= 1000 && unit < units.length - 1);
        const digits = n >= 100 ? 0 : n >= 10 ? 1 : 2;
        return n.toFixed(digits) + " " + units[unit];
      }

      function percentOf(bytes, total) {
        if (!total || total <= 0) return 0;
        return Math.max(0, Math.min(100, Math.floor((bytes / total) * 100)));
      }

      function openDb() {
        if (dbPromise) return dbPromise;
        dbPromise = new Promise((resolve, reject) => {
          if (!("indexedDB" in window)) {
            reject(new DownloadError("NO_INDEXEDDB", "IndexedDB is unavailable."));
            return;
          }
          const request = indexedDB.open(DB_NAME, DB_VERSION);
          request.onupgradeneeded = () => {
            const db = request.result;
            if (!db.objectStoreNames.contains("chunks")) {
              const chunks = db.createObjectStore("chunks", { keyPath: ["game", "index"] });
              chunks.createIndex("game", "game", { unique: false });
            }
            if (!db.objectStoreNames.contains("meta")) {
              db.createObjectStore("meta", { keyPath: "game" });
            }
          };
          request.onsuccess = () => {
            const db = request.result;
            db.onversionchange = () => db.close();
            resolve(db);
          };
          request.onerror = () => reject(request.error || new DownloadError("DB_OPEN", "Could not open the local vault."));
          request.onblocked = () => reject(new DownloadError("DB_BLOCKED", "Close other launcher tabs and try again."));
        });
        return dbPromise;
      }

      async function getMeta(gameKey) {
        const db = await openDb();
        return new Promise((resolve, reject) => {
          const tx = db.transaction("meta", "readonly");
          const request = tx.objectStore("meta").get(gameKey);
          request.onsuccess = () => resolve(request.result || null);
          request.onerror = () => reject(request.error);
          tx.onabort = () => reject(tx.error);
        });
      }

      async function putMeta(meta) {
        const db = await openDb();
        return new Promise((resolve, reject) => {
          const tx = db.transaction("meta", "readwrite");
          tx.objectStore("meta").put(meta);
          tx.oncomplete = () => resolve();
          tx.onerror = () => reject(tx.error);
          tx.onabort = () => reject(tx.error);
        });
      }

      async function putChunk(gameKey, index, data) {
        const db = await openDb();
        return new Promise((resolve, reject) => {
          const tx = db.transaction("chunks", "readwrite");
          tx.objectStore("chunks").put({ game: gameKey, index: index, data: data });
          tx.oncomplete = () => resolve();
          tx.onerror = () => reject(tx.error);
          tx.onabort = () => reject(tx.error);
        });
      }

      async function getChunks(gameKey) {
        const db = await openDb();
        return new Promise((resolve, reject) => {
          const tx = db.transaction("chunks", "readonly");
          const request = tx.objectStore("chunks").index("game").getAll(IDBKeyRange.only(gameKey));
          request.onsuccess = () => {
            const rows = request.result || [];
            rows.sort((a, b) => a.index - b.index);
            resolve(rows);
          };
          request.onerror = () => reject(request.error);
          tx.onabort = () => reject(tx.error);
        });
      }

      async function countChunks(gameKey) {
        const db = await openDb();
        return new Promise((resolve, reject) => {
          const tx = db.transaction("chunks", "readonly");
          const request = tx.objectStore("chunks").index("game").count(IDBKeyRange.only(gameKey));
          request.onsuccess = () => resolve(request.result);
          request.onerror = () => reject(request.error);
          tx.onabort = () => reject(tx.error);
        });
      }

      async function clearStoredGame(gameKey) {
        const db = await openDb();
        return new Promise((resolve, reject) => {
          const tx = db.transaction(["chunks", "meta"], "readwrite");
          tx.objectStore("meta").delete(gameKey);
          const cursorRequest = tx.objectStore("chunks").index("game").openCursor(IDBKeyRange.only(gameKey));
          cursorRequest.onsuccess = () => {
            const cursor = cursorRequest.result;
            if (cursor) {
              cursor.delete();
              cursor.continue();
            }
          };
          tx.oncomplete = () => resolve();
          tx.onerror = () => reject(tx.error);
          tx.onabort = () => reject(tx.error);
        });
      }

      async function requestPersistence() {
        if (persistenceRequested) return;
        persistenceRequested = true;
        try {
          if (navigator.storage && navigator.storage.persist) {
            await navigator.storage.persist();
          }
        } catch (_) {}
      }

      function makeUi(button) {
        return {
          el: button,
          status: button.querySelector(".status-text"),
          fill: button.querySelector(".progress-fill"),
          track: button.querySelector(".progress-track")
        };
      }

      function initUi() {
        ["fortnite", "minecraft"].forEach((gameKey) => {
          ui[gameKey] = {
            run: makeUi(document.querySelector('.btn[data-game="' + gameKey + '"][data-action="run"]')),
            clear: makeUi(document.querySelector('.btn[data-game="' + gameKey + '"][data-action="clear"]'))
          };
        });
      }

      function setFill(gameKey, percent) {
        const target = ui[gameKey].run.fill;
        if (!target) return;
        target.setAttribute("width", String(Math.round((TRACK_WIDTH * percent) / 100)));
      }

      function clearModes(el) {
        el.classList.remove("is-ready", "is-partial", "is-busy", "is-error", "is-success");
      }

      function modeClass(mode) {
        if (mode === "ready") return "is-ready";
        if (mode === "partial") return "is-partial";
        if (mode === "downloading" || mode === "launching") return "is-busy";
        if (mode === "error") return "is-error";
        if (mode === "success") return "is-success";
        return "";
      }

      function paint(gameKey, mode, options) {
        const opts = options || {};
        const game = GAMES[gameKey];
        const meta = opts.meta !== undefined ? opts.meta : app.meta[gameKey];
        const run = ui[gameKey].run;
        const clear = ui[gameKey].clear;
        const savedBytes = meta ? Number(meta.bytes) || 0 : 0;
        const total = meta ? Number(meta.total) || game.bytes : game.bytes;
        const hasData = !!meta && (!!meta.complete || savedBytes > 0);
        const busy = app.activeDownload === gameKey || app.launching[gameKey] || app.clearing[gameKey];
        const pct = meta && meta.complete ? 100 : percentOf(savedBytes, total);

        clearModes(run.el);
        clearModes(clear.el);
        const runMode = modeClass(mode);
        if (runMode) run.el.classList.add(runMode);
        if (mode === "ready") run.el.classList.add("is-ready");
        if (mode === "success") run.el.classList.add("is-success");
        run.el.setAttribute("aria-busy", mode === "downloading" || mode === "launching" ? "true" : "false");
        run.el.setAttribute("aria-disabled", mode === "downloading" || mode === "launching" || app.clearing[gameKey] ? "true" : "false");

        let runText = "";
        if (mode === "checking") runText = "CHECKING LOCAL CACHE";
        else if (mode === "empty") runText = "DOWNLOAD & PLAY · " + formatBytes(game.bytes);
        else if (mode === "partial") runText = "RESUME · " + pct + "% SAVED · " + formatBytes(savedBytes);
        else if (mode === "ready") runText = "READY · " + formatBytes(total);
        else if (mode === "downloading") runText = opts.text || "DOWNLOADING · " + pct + "%";
        else if (mode === "launching") runText = opts.text || "ASSEMBLING LOCAL BUILD…";
        else if (mode === "success") runText = opts.text || "READY · " + formatBytes(total);
        else if (mode === "error") runText = opts.text || "DOWNLOAD FAILED · TAP TO RETRY";
        else if (mode === "cleared") runText = "CLEARED · DOWNLOAD AGAIN";
        else runText = "READY · " + formatBytes(total);

        run.status.textContent = runText;
        run.el.setAttribute("aria-label", "Run " + game.name + ". " + runText + ".");

        const showProgress = mode === "downloading" || mode === "partial" || mode === "ready";
        setFill(gameKey, showProgress ? pct : 0);
        if (run.track) run.track.style.opacity = showProgress ? "1" : "0";

        clear.el.classList.toggle("is-armed", hasData);
        let clearText = "NOTHING SAVED";
        if (app.clearing[gameKey]) clearText = "CLEARING…";
        else if (mode === "downloading" || mode === "launching") clearText = "IN USE";
        else if (hasData && meta && meta.complete) clearText = "REMOVE LOCAL COPY · " + formatBytes(total);
        else if (hasData) clearText = "REMOVE PARTIAL · " + pct + "%";
        clear.status.textContent = clearText;

        const clearDisabled = !hasData || busy;
        clear.el.classList.toggle("is-disabled", clearDisabled);
        clear.el.setAttribute("aria-disabled", clearDisabled ? "true" : "false");
        clear.el.setAttribute("aria-label", "Clear " + game.name + ". " + clearText + ".");
      }

      function paintResting(gameKey) {
        const meta = app.meta[gameKey];
        if (meta && meta.complete) paint(gameKey, "ready", { meta: meta });
        else if (meta && (Number(meta.bytes) || 0) > 0) paint(gameKey, "partial", { meta: meta });
        else paint(gameKey, "empty", { meta: meta });
      }

      async function refresh(gameKey) {
        try {
          const meta = await getMeta(gameKey);
          app.meta[gameKey] = meta;
          if (app.activeDownload !== gameKey && !app.launching[gameKey] && !app.clearing[gameKey]) {
            paintResting(gameKey);
          }
        } catch (error) {
          paint(gameKey, "error", { text: "LOCAL STORAGE UNAVAILABLE" });
        }
      }

      async function refreshAll() {
        ["fortnite", "minecraft"].forEach((key) => paint(key, "checking"));
        await Promise.all(["fortnite", "minecraft"].map((key) => refresh(key)));
      }

      function flash(gameKey, mode, text, duration) {
        paint(gameKey, mode, { text: text });
        window.setTimeout(() => {
          if (app.activeDownload !== gameKey && !app.launching[gameKey] && !app.clearing[gameKey]) {
            paintResting(gameKey);
          }
        }, duration || 3600);
      }

      async function downloadGame(gameKey, onProgress) {
        const game = GAMES[gameKey];
        const driveKey = ensureDriveKey();
        if (!driveKey) throw new DownloadError("NO_KEY", "A Google Drive API key is required.");
        let previous = await getMeta(gameKey);

        if (previous && previous.complete) return previous;

        let resumeAt = 0;
        let chunkIndex = 0;
        if (previous && (Number(previous.bytes) || 0) > 0) {
          const actualChunks = await countChunks(gameKey);
          const expectedChunks = Number(previous.chunks) || 0;
          if (actualChunks === expectedChunks && Number(previous.bytes) < Number(previous.total || game.bytes)) {
            resumeAt = Number(previous.bytes);
            chunkIndex = expectedChunks;
          } else {
            await clearStoredGame(gameKey);
            previous = null;
          }
        }

        await requestPersistence();

        const baseMeta = {
          game: gameKey,
          name: game.name,
          file: game.file,
          total: Number(previous && previous.total) || game.bytes,
          bytes: resumeAt,
          chunks: chunkIndex,
          complete: false,
          mime: "text/html",
          updatedAt: Date.now()
        };
        await putMeta(baseMeta);

        const headers = {};
        if (resumeAt > 0) headers.Range = "bytes=" + resumeAt + "-";

        let response;
        try {
          response = await fetch(downloadUrl(game, driveKey), {
            mode: "cors",
            cache: "no-store",
            credentials: "omit",
            headers: headers
          });
        } catch (error) {
          throw new DownloadError("NETWORK", "Could not reach Google Drive.");
        }

        if (!response.ok && response.status !== 206) {
          let detail = "";
          try {
            const body = await response.clone().text();
            const parsed = JSON.parse(body);
            detail = parsed && parsed.error && parsed.error.message ? parsed.error.message : "";
          } catch (_) {}
          if (response.status === 400 || response.status === 401 || response.status === 403) {
            if (/api key|referer|credential|permission|not valid/i.test(detail)) {
              rejectedDriveKey = driveKey;
              forgetDriveKey();
              throw new DownloadError("API_KEY", detail || "The Google Drive API key was rejected.");
            }
          }
          throw new DownloadError("HTTP_" + response.status, "Google Drive returned HTTP " + response.status + ".");
        }

        if (resumeAt > 0 && response.status === 200) {
          await clearStoredGame(gameKey);
          resumeAt = 0;
          chunkIndex = 0;
          await putMeta(baseMeta);
        }

        let total = Number(baseMeta.total) || game.bytes;
        const contentRange = response.headers.get("content-range");
        if (contentRange) {
          const match = /\/(\d+)\s*$/.exec(contentRange);
          if (match) total = Number(match[1]);
        } else {
          const contentLength = Number(response.headers.get("content-length"));
          if (contentLength > 0) total = response.status === 206 ? resumeAt + contentLength : contentLength;
        }

        if (!response.body || typeof response.body.getReader !== "function") {
          throw new DownloadError("NO_STREAM", "This browser cannot stream the download.");
        }

        const reader = response.body.getReader();
        let streamed = 0;
        let saved = resumeAt;
        let batch = [];
        let batchBytes = 0;
        let lastPaint = 0;
        let failed = false;

        const flush = async (force) => {
          if (!batchBytes) return;
          if (!force && batchBytes < CHUNK_BYTES) return;
          const blob = new Blob(batch, { type: "application/octet-stream" });
          await putChunk(gameKey, chunkIndex, blob);
          chunkIndex += 1;
          saved += batchBytes;
          batch = [];
          batchBytes = 0;
          await putMeta({
            game: gameKey,
            name: game.name,
            file: game.file,
            total: total,
            bytes: saved,
            chunks: chunkIndex,
            complete: false,
            mime: "text/html",
            updatedAt: Date.now()
          });
          if (onProgress) onProgress(saved, total);
        };

        try {
          while (true) {
            const read = await reader.read();
            if (read.done) break;
            if (!read.value) continue;
            const bytes = read.value instanceof Uint8Array ? read.value : new Uint8Array(read.value);
            batch.push(bytes);
            batchBytes += bytes.byteLength;
            streamed += bytes.byteLength;

            const now = Date.now();
            if (now - lastPaint > 110) {
              lastPaint = now;
              if (onProgress) onProgress(Math.min(resumeAt + streamed, total), total);
            }

            if (batchBytes >= CHUNK_BYTES) await flush(false);
          }
          await flush(true);
        } catch (error) {
          failed = true;
          try { await reader.cancel(); } catch (_) {}
          if (error && (error.name === "QuotaExceededError" || /quota|storage/i.test(error.message || ""))) {
            throw new DownloadError("QUOTA", "Not enough local storage for this build.");
          }
          if (error instanceof DownloadError) throw error;
          throw new DownloadError("WRITE_FAILED", "The local write was interrupted.");
        } finally {
          if (!failed) {
            try { reader.releaseLock(); } catch (_) {}
          }
        }

        if (total > 0 && saved < total) {
          throw new DownloadError("INCOMPLETE", "The connection closed before the build finished downloading.");
        }

        const completed = {
          game: gameKey,
          name: game.name,
          file: game.file,
          total: total,
          bytes: saved,
          chunks: chunkIndex,
          complete: true,
          mime: "text/html",
          savedAt: Date.now(),
          updatedAt: Date.now()
        };
        await putMeta(completed);
        if (onProgress) onProgress(saved, total);
        return completed;
      }

      async function assembleBlob(gameKey, meta) {
        const rows = await getChunks(gameKey);
        if (!rows.length) throw new DownloadError("EMPTY", "No saved chunks were found.");
        if (meta && meta.complete && Number(meta.chunks) && rows.length < Number(meta.chunks)) {
          throw new DownloadError("MISSING_CHUNKS", "The local build is incomplete.");
        }
        const parts = rows.map((row) => row.data instanceof Blob ? row.data : new Blob([row.data]));
        const blob = new Blob(parts, { type: "text/html" });
        if (!blob.size) throw new DownloadError("EMPTY_BLOB", "The local build is empty.");
        return blob;
      }

      function openStage(game) {
        let tab = null;
        try {
          tab = window.open("about:blank", "_blank");
        } catch (_) {
          return null;
        }
        if (!tab) return null;

        try {
          const doc = tab.document;
          const head = doc.head || doc.documentElement.appendChild(doc.createElement("head"));
          head.innerHTML = `
<meta charset="utf-8">
<meta name="referrer" content="no-referrer">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Preparing ${game.name}</title>
<style>
  :root { color-scheme: dark; }
  * { box-sizing: border-box; }
  html, body { height: 100%; }
  body {
    margin: 0;
    display: grid;
    place-items: center;
    overflow: hidden;
    background:
      radial-gradient(900px 600px at 15% 0%, color-mix(in srgb, ${game.accent} 13%, transparent), transparent 70%),
      radial-gradient(800px 600px at 100% 100%, rgba(92, 111, 255, .11), transparent 70%),
      #05060a;
    color: #f6f7fb;
    font-family: "SF Pro Display", Inter, "Segoe UI", -apple-system, BlinkMacSystemFont, Arial, sans-serif;
  }
  body::before {
    content: "";
    position: fixed;
    inset: 0;
    pointer-events: none;
    opacity: .04;
    background-image: linear-gradient(rgba(255,255,255,.8) 1px, transparent 1px), linear-gradient(90deg, rgba(255,255,255,.8) 1px, transparent 1px);
    background-size: 48px 48px;
    mask-image: radial-gradient(circle at 50% 45%, #000, transparent 72%);
  }
  .stage {
    position: relative;
    width: min(760px, calc(100vw - 48px));
    padding: 34px 38px 28px;
    border: 1px solid rgba(255,255,255,.09);
    border-radius: 28px;
    background: linear-gradient(145deg, rgba(22,26,41,.94), rgba(10,12,20,.96));
    box-shadow: 0 30px 90px rgba(0,0,0,.55), inset 0 1px rgba(255,255,255,.05);
    overflow: hidden;
  }
  .stage::before {
    content: "";
    position: absolute;
    inset: -35% -10% auto auto;
    width: 460px;
    height: 460px;
    border-radius: 50%;
    background: radial-gradient(circle, color-mix(in srgb, ${game.accent} 18%, transparent), transparent 68%);
    pointer-events: none;
  }
  .top { position: relative; display: flex; justify-content: space-between; align-items: center; margin-bottom: 74px; }
  .tag { display: inline-flex; align-items: center; gap: 9px; font-size: 10px; font-weight: 700; letter-spacing: .22em; color: #aeb6ca; }
  .tag i { width: 7px; height: 7px; border-radius: 50%; background: ${game.accent}; box-shadow: 0 0 12px ${game.accent}; animation: pulse 1.4s ease-in-out infinite; }
  .idx { font-size: 11px; letter-spacing: .2em; color: rgba(255,255,255,.27); font-variant-numeric: tabular-nums; }
  h1 { position: relative; margin: 0 0 14px; font-size: clamp(42px, 8vw, 78px); line-height: .92; letter-spacing: -.055em; font-weight: 650; }
  h1 em { font-style: normal; color: ${game.accent}; }
  .phase { position: relative; margin: 0 0 30px; color: #c5cada; font-size: 14px; font-weight: 500; letter-spacing: .01em; }
  .meter { position: relative; height: 6px; border-radius: 99px; overflow: hidden; background: rgba(255,255,255,.08); }
  .meter i { display: block; width: 0; height: 100%; border-radius: inherit; background: linear-gradient(90deg, ${game.accent2}, ${game.accent}); box-shadow: 0 0 14px ${game.accent}; transition: width .22s ease; }
  .row { position: relative; display: flex; justify-content: space-between; gap: 20px; margin-top: 14px; font-size: 11px; font-weight: 600; letter-spacing: .09em; color: #8b92a6; font-variant-numeric: tabular-nums; }
  .pct { color: #e9ecf5; }
  .note { position: relative; margin: 48px 0 0; padding-top: 18px; border-top: 1px solid rgba(255,255,255,.06); color: #686f83; font-size: 11px; letter-spacing: .015em; }
  .note code { color: #aab2c7; font-family: "SFMono-Regular", Consolas, monospace; }
  .stage.is-error .meter i { background: #ff6b7a; box-shadow: 0 0 14px #ff6b7a; }
  .stage.is-error .tag i { background: #ff6b7a; box-shadow: 0 0 12px #ff6b7a; }
  .stage.is-error h1 em { color: #ff8a97; }
  @keyframes pulse { 0%,100% { opacity: 1; } 50% { opacity: .35; } }
  @media (max-width: 560px) {
    .stage { padding: 26px 24px 22px; }
    .top { margin-bottom: 52px; }
    .note { margin-top: 32px; }
  }
</style>`;
          const body = doc.body || doc.documentElement.appendChild(doc.createElement("body"));
          body.innerHTML = `
  <main class="stage">
    <div class="top">
      <span class="tag"><i></i> LOCAL PLAY</span>
      <span class="idx">${stageNumber(game)} / 04</span>
    </div>
    <h1>Preparing<br><em>${game.name}</em></h1>
    <p class="phase">Opening a blank tab and checking the local vault…</p>
    <div class="meter"><i></i></div>
    <div class="row"><span class="pct">0%</span><span class="detail">0 B</span></div>
    <p class="note">This tab stays <code>about:blank</code>. Everything runs from the copy on your device.</p>
  </main>`;
          doc.title = "Preparing " + game.name;
          tab.focus();
          return tab;
        } catch (error) {
          try { tab.close(); } catch (_) {}
          return null;
        }
      }

      function stageNumber(game) {
        return game.name === "Fortnite" ? "01" : "02";
      }

      function updateStage(tab, percent, phase, detail) {
        if (!tab || tab.closed) return;
        try {
          const doc = tab.document;
          const fill = doc.querySelector(".meter i");
          const phaseEl = doc.querySelector(".phase");
          const pctEl = doc.querySelector(".pct");
          const detailEl = doc.querySelector(".detail");
          if (fill) fill.style.width = Math.max(0, Math.min(100, percent)) + "%";
          if (phaseEl && phase) phaseEl.textContent = phase;
          if (pctEl) pctEl.textContent = Math.round(percent) + "%";
          if (detailEl && detail !== undefined) detailEl.textContent = detail;
        } catch (_) {}
      }

      function failStage(tab, title, detail) {
        if (!tab || tab.closed) return;
        try {
          const doc = tab.document;
          const stage = doc.querySelector(".stage");
          if (stage) stage.classList.add("is-error");
          doc.title = title;
          const heading = doc.querySelector("h1");
          if (heading) heading.innerHTML = title + "<br><em>paused</em>";
          const phase = doc.querySelector(".phase");
          if (phase) phase.textContent = detail;
          const pct = doc.querySelector(".pct");
          if (pct) pct.textContent = "—";
          const meter = doc.querySelector(".meter i");
          if (meter) meter.style.width = "100%";
          const note = doc.querySelector(".note");
          if (note) note.textContent = "Close this tab, then tap Run again in the launcher to retry.";
        } catch (_) {}
      }

      function launchBlob(tab, game, blob) {
        const url = URL.createObjectURL(blob);
        const doc = tab.document;
        const iframe = doc.createElement("iframe");
        iframe.title = game.name;
        iframe.allow = "fullscreen; autoplay; gamepad";
        iframe.allowFullscreen = true;
        iframe.referrerPolicy = "no-referrer";
        iframe.style.cssText = "position:fixed;inset:0;width:100%;height:100%;border:0;background:#000;display:block";
        iframe.src = url;

        doc.title = game.name;
        doc.documentElement.style.background = "#000";
        doc.body.style.cssText = "margin:0;padding:0;overflow:hidden;background:#000;display:block";
        doc.body.replaceChildren(iframe);

        window.setTimeout(() => {
          try {
            iframe.focus();
            tab.focus();
          } catch (_) {}
        }, 140);

        try {
          tab.addEventListener("pagehide", () => URL.revokeObjectURL(url), { once: true });
        } catch (_) {
          window.setTimeout(() => URL.revokeObjectURL(url), 60 * 60 * 1000);
        }
        return url;
      }

      function friendlyError(error) {
        if (!navigator.onLine) return "OFFLINE — CHECK YOUR CONNECTION";
        if (!error) return "DOWNLOAD FAILED — TAP TO RETRY";
        if (error.code === "QUOTA" || error.name === "QuotaExceededError") return "NOT ENOUGH STORAGE — CLEAR A BUILD";
        if (error.code === "API_KEY") return "DRIVE API KEY INVALID — TAP RUN TO RE-ENTER";
        if (error.code === "NO_KEY") return "DRIVE API KEY REQUIRED — TAP RUN";
        if (error.code === "DRIVE_WARNING" || error.code === "HTTP_403") return "DRIVE BLOCKED THE DOWNLOAD — TRY AGAIN";
        if (error.code === "HTTP_404") return "FILE NOT FOUND ON DRIVE";
        if (error.code === "NO_STREAM") return "THIS BROWSER CANNOT STREAM THE FILE";
        if (error.code === "MISSING_CHUNKS" || error.code === "EMPTY") return "LOCAL SAVE IS CORRUPTED — CLEAR IT";
        if (error.code === "NETWORK") return "NETWORK LOST — TAP TO RESUME";
        if (error.code === "INCOMPLETE") return "DOWNLOAD PAUSED — TAP TO RESUME";
        return "DOWNLOAD FAILED — TAP TO RETRY";
      }

      async function runGame(gameKey) {
        const game = GAMES[gameKey];

        if (app.activeDownload && app.activeDownload !== gameKey) {
          flash(gameKey, "error", "ONE DOWNLOAD AT A TIME", 2600);
          return;
        }
        if (app.activeDownload === gameKey || app.launching[gameKey] || app.clearing[gameKey]) return;

        const metaNow = app.meta[gameKey];
        if ((!metaNow || !metaNow.complete) && !readDriveKey()) {
          const key = ensureDriveKey();
          if (!key) {
            flash(gameKey, "error", "DRIVE API KEY REQUIRED", 4400);
            return;
          }
        }

        const tab = openStage(game);
        if (!tab) {
          flash(gameKey, "error", "ALLOW POP-UPS, THEN TAP RUN", 4400);
          return;
        }

        app.launching[gameKey] = true;
        const startBytes = app.meta[gameKey] && Number(app.meta[gameKey].bytes) || 0;
        const startedAt = Date.now();
        let lastBytes = startBytes;
        let lastTime = startedAt;
        let failed = false;
        let errorText = "";

        try {
          let meta = await getMeta(gameKey);
          app.meta[gameKey] = meta;

          if (!meta || !meta.complete) {
            app.activeDownload = gameKey;
            paint(gameKey, "downloading", {
              meta: meta,
              text: meta && meta.bytes ? "RESUMING · " + percentOf(meta.bytes, meta.total) + "%" : "CONNECTING TO GOOGLE DRIVE…"
            });
            updateStage(tab, 0, meta && meta.bytes ? "Resuming the download" : "Downloading from Google Drive", "Connecting…");

            meta = await downloadGame(gameKey, (bytes, total) => {
              const pct = percentOf(bytes, total);
              const now = Date.now();
              const elapsed = Math.max(1, now - lastTime);
              const speed = Math.max(0, bytes - lastBytes) / (elapsed / 1000);
              lastBytes = bytes;
              lastTime = now;
              app.meta[gameKey] = { game: gameKey, bytes: bytes, total: total, complete: false };
              paint(gameKey, "downloading", {
                meta: app.meta[gameKey],
                text: "DOWNLOADING · " + pct + "% · " + formatBytes(bytes) + " / " + formatBytes(total)
              });
              updateStage(
                tab,
                pct,
                pct < 100 ? "Downloading from Google Drive" : "Download complete",
                formatBytes(bytes) + " of " + formatBytes(total) +
                  (speed > 0 ? "  ·  " + formatBytes(speed) + "/s" : "")
              );
            });

            app.meta[gameKey] = meta;
            app.activeDownload = null;
          }

          if (tab.closed) {
            paint(gameKey, "success", {
              meta: meta,
              text: "SAVED · TAP RUN TO PLAY"
            });
            return;
          }

          paint(gameKey, "launching", { meta: meta, text: "ASSEMBLING LOCAL BUILD…" });
          updateStage(tab, 94, "Assembling from IndexedDB", "Reading local chunks…");

          const blob = await assembleBlob(gameKey, meta);
          updateStage(tab, 100, "Starting game", formatBytes(blob.size) + " ready");

          if (tab.closed) {
            paint(gameKey, "success", { meta: meta, text: "SAVED · TAP RUN TO PLAY" });
            return;
          }

          launchBlob(tab, game, blob);
          paint(gameKey, "success", { meta: meta, text: "PLAYING IN NEW TAB" });
        } catch (error) {
          failed = true;
          if (error && error.code === "QUOTA") {
            try { await clearStoredGame(gameKey); } catch (_) {}
            app.meta[gameKey] = null;
          }
          errorText = friendlyError(error);
          console.error("[local-play]", error);
          paint(gameKey, "error", { text: errorText, meta: app.meta[gameKey] });
          failStage(tab, "Download", errorText + ". " + (GAMES[gameKey].name + " is safe to retry from the launcher."));
        } finally {
          app.activeDownload = null;
          app.launching[gameKey] = false;
          if (failed) {
            paint(gameKey, "error", { text: errorText, meta: app.meta[gameKey] });
          } else {
            await refresh(gameKey);
          }
        }
      }

      async function clearGame(gameKey) {
        if (app.activeDownload === gameKey || app.launching[gameKey] || app.clearing[gameKey]) return;
        const meta = app.meta[gameKey];
        if (!meta || (!meta.complete && !(Number(meta.bytes) > 0))) return;

        app.clearing[gameKey] = true;
        paint(gameKey, "cleared", { meta: meta, text: "CLEARING LOCAL COPY…" });
        try {
          await clearStoredGame(gameKey);
          app.meta[gameKey] = null;
          app.clearing[gameKey] = false;
          paint(gameKey, "cleared", { meta: null, text: "CLEARED · DOWNLOAD AGAIN" });
          window.setTimeout(() => {
            if (!app.activeDownload && !app.launching[gameKey] && !app.clearing[gameKey]) {
              paintResting(gameKey);
            }
          }, 1900);
        } catch (error) {
          console.error("[local-play]", error);
          paint(gameKey, "error", { meta: meta, text: "COULD NOT CLEAR LOCAL DATA" });
        } finally {
          app.clearing[gameKey] = false;
        }
      }

      function bind() {
        document.querySelectorAll(".btn").forEach((button) => {
          const gameKey = button.getAttribute("data-game");
          const action = button.getAttribute("data-action");

          button.addEventListener("click", () => {
            if (action === "run") runGame(gameKey);
            else clearGame(gameKey);
          });

          button.addEventListener("keydown", (event) => {
            if (event.key === "Enter" || event.key === " " || event.key === "Spacebar") {
              event.preventDefault();
              if (action === "run") runGame(gameKey);
              else clearGame(gameKey);
            }
          });
        });
      }

      async function init() {
        initUi();
        bind();
        await refreshAll();
      }

      init();
    })();
